        "level_up_next_milestone_hint": ["de": "Nächste Belohnung bald verfügbar!", "en": "Next reward coming soon!", "es": "¡Próxima recompensa pronto!", "fr": "Prochaine récompense bientôt disponible !", "it": "Next reward coming soon!", "pt": "Próxima recompensa em breve!", "ja": "次の報酬は近日公開予定です！", "ko": "다음 보상이 곧 찾아옵니다!", "pl": "Kolejna nagroda już wkrótce!", "nl": "Volgende beloning binnenkort!", "tr": "Bir sonraki ödül çok yakında!"],
        "level_up_pass_hint": ["de": "Besuche den Garten-Pass für deine Belohnung!", "en": "Check the Garden Pass to claim your rewards!", "es": "¡Revisa el Pase del Jardín para reclamar tus recompensas!", "fr": "Consulte le Passe du jardin pour ta récompense !", "it": "Check the Garden Pass to claim your rewards!", "pt": "Visita o Passe do jardim para a tua recompensa!", "ja": "ガーデンパスをチェックして報酬を受け取りましょう！", "ko": "가든 패스를 확인하고 보상을 받으세요!", "pl": "Sprawdź Garden Pass, aby odebrać nagrody!", "nl": "Controleer de Garden Pass om je beloningen te claimen!", "tr": "Ödüllerinizi almak için Garden Pass'ı kontrol edin!"],
        "level_up_spin_verdient_desc": ["de": "Drehe das Rad für Münzen, Power-Ups und Pflanzen", "en": "Spin the wheel for coins, power-ups, and plants", "es": "Gira la ruleta para conseguir monedas, power-ups y plantas", "fr": "Tourne la roue pour des pièces, des power-ups et des plantes", "it": "Spin the wheel for coins, power-ups, and plants", "pt": "Gira a roda para moedas, power-ups e plantas", "ja": "ホイールを回してコイン、パワーアップ、植物を入手", "ko": "룰렛을 돌려 코인, 파워업, 식물을 얻으세요", "pl": "Zakręć kołem, aby zdobyć monety, ulepszenia i rośliny", "nl": "Draai aan het wiel voor munten, power-ups en planten", "tr": "Paralar, güçlendiriciler ve bitkiler için çarkı döndürün"],
        "level_up_spin_verdient_titel": ["de": "+%d Glücksrad-Drehung(en) verdient!", "en": "+%d spin(s) earned!", "es": "+%d giro(s) ganado(s)!", "fr": "+%d tour(s) gagné(s) !", "it": "+%d spin(s) earned!", "pt": "+%d rotação(ões) ganhas!", "ja": "+%d スピン獲得!", "ko": "+%d개의 스핀을 획득했습니다!", "pl": "+%d zdobytych spinów!", "nl": "+%d spin(s) verdiend!", "tr": "+%d dönüş kazanıldı!"],
        "level_up_weiter": ["de": "Super!", "en": "Awesome!", "es": "¡Genial!", "fr": "Super !", "it": "Awesome!", "pt": "Ótimo!", "ja": "素晴らしい！", "ko": "엄청난!", "pl": "Wspaniały!", "nl": "Geweldig!", "tr": "Mükemmel!"],
        "month.1": ["de": "Januar", "en": "January", "es": "Enero", "fr": "Janvier", "it": "Gennaio", "pt": "Janeiro", "ja": "1月", "ko": "1월", "pl": "Styczeń", "nl": "Januari", "tr": "Ocak"],
        "month.2": ["de": "Februar", "en": "February", "es": "Febrero", "fr": "Février", "it": "Febbraio", "pt": "Fevereiro", "ja": "2月", "ko": "2월", "pl": "Luty", "nl": "Februari", "tr": "Şubat"],
