        "streak.motivation.0": ["de": "Bleib am Ball!", "en": "Keep it up!", "es": "¡Sigue así!", "fr": "Continue comme ça !", "it": "Keep it up!", "pt": "Continua assim!", "ja": "それを維持する！", "ko": "계속하세요!", "pl": "Tak trzymaj!", "nl": "Ga zo door!", "tr": "Aynen böyle devam!"],
        "streak.motivation.1": ["de": "Jeden Tag ein kleines Stück besser.", "en": "A little better every single day.", "es": "Cada día un poco mejor.", "fr": "Un peu mieux chaque jour.", "it": "A little better every single day.", "pt": "Um pouco melhor a cada dia.", "ja": "毎日少しずつ良くなっていきます。", "ko": "매일 조금씩 나아지세요.", "pl": "Z każdym dniem trochę lepiej.", "nl": "Elke dag een beetje beter.", "tr": "Her geçen gün biraz daha iyi."],
        "streak.motivation.2": ["de": "Dranbleiben zahlt sich aus!", "en": "Consistency pays off!", "es": "¡La constancia tiene su recompensa!", "fr": "La constance paie !", "it": "Consistency pays off!", "pt": "A consistência compensa!", "ja": "一貫性が功を奏します！", "ko": "일관성이 성과를 냅니다!", "pl": "Konsekwencja się opłaca!", "nl": "Consistentie loont!", "tr": "Tutarlılık karşılığını verir!"],
        "streak.motivation.3": ["de": "Du bist stärker als du denkst.", "en": "You are stronger than you think.", "es": "Eres más fuerte de lo que crees.", "fr": "Tu es plus fort que tu ne le penses.", "it": "You are stronger than you think.", "pt": "És mais forte do que pensas.", "ja": "あなたは思っているより強いです。", "ko": "당신은 당신이 생각하는 것보다 더 강하다.", "pl": "Jesteś silniejszy niż myślisz.", "nl": "Je bent sterker dan je denkt.", "tr": "Düşündüğünden daha güçlüsün."],
        "streak.motivation.4": ["de": "Unkraut wächst nicht in gepflegten Gärten.", "en": "Weeds don't grow in well-kept gardens.", "es": "La maleza no crece en jardines cuidados.", "fr": "Les mauvaises herbes ne poussent pas dans les jardins bien entretenus.", "it": "Weeds don't grow in well-kept gardens.", "pt": "As ervas daninhas não crescem em jardins bem cuidados.", "ja": "手入れの行き届いた庭には雑草は生えません。", "ko": "잘 관리된 정원에서는 잡초가 자라지 않습니다.", "pl": "Chwasty nie rosną w dobrze utrzymanych ogrodach.", "nl": "In goed onderhouden tuinen groeit onkruid niet.", "tr": "Bakımlı bahçelerde yabani otlar yetişmez."],
        "streak.motivation.5": ["de": "Routine schlägt Motivation.", "en": "Routine beats motivation.", "es": "La rutina vence a la motivación.", "fr": "La routine bat la motivation.", "it": "Routine beats motivation.", "pt": "A rotina vence a motivação.", "ja": "ルーチンはモチベーションに勝ります。", "ko": "일상이 동기를 이긴다.", "pl": "Rutyna pokonuje motywację.", "nl": "Routine verslaat motivatie.", "tr": "Rutin motivasyonu yener."],
        "streak.motivation.6": ["de": "Kleine Schritte, große Wirkung.", "en": "Small steps, big impact.", "es": "Pequeños pasos, gran impacto.", "fr": "Petits pas, grands effets.", "it": "Small steps, big impact.", "pt": "Pequenos passos, grande impacto.", "ja": "小さな一歩、大きな影響。", "ko": "작은 단계, 큰 영향.", "pl": "Małe kroki, duży wpływ.", "nl": "Kleine stappen, grote impact.", "tr": "Küçük adımlar, büyük etki."],
        "streak.motivation.7": ["de": "Dein Garten wächst mit dir!", "en": "Your garden grows with you!", "es": "¡Tu jardín crece contigo!", "fr": "Ton jardin grandit avec toi !", "it": "Your garden grows with you!", "pt": "O teu jardim cresce contigo!", "ja": "あなたの庭はあなたと一緒に成長します！", "ko": "당신의 정원은 당신과 함께 성장합니다!", "pl": "Twój ogród rośnie razem z Tobą!", "nl": "Uw tuin groeit met u mee!", "tr": "Bahçeniz sizinle birlikte büyüyor!"],
        "streak.motivation.8": ["de": "Konsistenz ist der Schlüssel.", "en": "Consistency is key.", "es": "La consistencia es la clave.", "fr": "La constance est la clé.", "it": "Consistency is key.", "pt": "A consistência é a chave.", "ja": "一貫性が重要です。", "ko": "일관성이 핵심입니다.", "pl": "Spójność jest kluczowa.", "nl": "Consistentie is de sleutel.", "tr": "Tutarlılık çok önemlidir."],
